 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Locate each independent frame-shaped component of color 5.
    unseen = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 5}
    while unseen:
        start = unseen.pop()
        stack = [start]
        comp = {start}
        while stack:
            r, c = stack.pop()
            for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if (nr, nc) in unseen:
                    unseen.remove((nr, nc))
                    comp.add((nr, nc))
                    stack.append((nr, nc))
        r0 = min(r for r, c in comp); r1 = max(r for r, c in comp)
        c0 = min(c for r, c in comp); c1 = max(c for r, c in comp)
        if r1-r0 < 2 or c1-c0 < 2:
            continue
        # The missing top-edge cell is the target of the incoming color-2 ray.
        top_gaps = [c for c in range(c0+1, c1) if grid[r0][c] != 5]
