            if r0 > 0:
                for c in range(gap+1):
                    if out[r0-1][c] == 0:
                        out[r0-1][c] = 2
            for r in range(r0+1, r1):
                for c in range(c0+1, c1):
                    if grid[r][c] == 0:
                        out[r][c] = 2
    return out
